using System;using System.Text.Json;using System.Collections.Generic;using Archigen;using Loremaker.Text;
class Program {static void Main(){var rows=new List<object>();for(int i=0;i<100;i++){var port=i%2==0;var t=new TextTemplate("The keeper works at the $place.").Substitute("place",new ConstantValue<string>(port?"harbour":"workshop"));t.Add("At the harbour, the keeper checks the mooring ledger.","harbour");t.Add("In the workshop, the keeper measures replacement handles.","workshop");t.Add("The $place closes before dusk.");string a=t.Next(),b=t.Next();if(a!=b||a.Contains(port?"replacement handles":"mooring ledger"))throw new Exception("Context or replay failure");rows.Add(new {index=i,port=port,text=a,replay=true});}Console.WriteLine(JsonSerializer.Serialize(rows));}}
